// Original visit-local teaching model. No notebook reads, normalization or writes.
export const phaseStages=Object.freeze([
 [-5,12,0,'Cold ice','All twelve symbols are ice in an open, ordered pattern. Molecules in ice still vibrate around their positions. This model stops here; energy entering warms the ice toward zero degrees Celsius.'],
 [0,12,0,'Ice at its melting point','All twelve symbols are ice at zero degrees Celsius. Energy entering can melt some ice without raising the temperature; energy leaving can cool this ice below zero.'],
 [0,8,4,'Mostly ice, some liquid','Eight symbols are in ice and four are in liquid at zero degrees Celsius. Adding energy melts more ice; removing energy freezes more liquid without changing the temperature.'],
 [0,4,8,'Mostly liquid, some ice','Four symbols are in ice and eight are in liquid at zero degrees Celsius. Adding energy melts more ice; removing energy freezes more liquid without changing the temperature.'],
 [0,0,12,'All liquid at its melting point','All twelve symbols are liquid at zero degrees Celsius. Energy leaving can start freezing without lowering the temperature; energy entering can warm this liquid above zero.'],
 [5,0,12,'Warmer liquid','All twelve symbols are liquid at plus five degrees Celsius. In this single liquid phase, adding energy can raise the temperature and removing energy can lower it. This model stops here; the picture does not measure molecular speed or density.']
].map(([temperature,solid,liquid,title,body])=>Object.freeze({temperature,solid,liquid,title,body})));
export const phaseRadius=7;
export function phaseStage(index){return Number.isInteger(index)&&index>=0&&index<6?phaseStages[index]:null;}
export function phaseStep(index,direction){return phaseStage(index)&&[-1,1].includes(direction)?Math.max(0,Math.min(5,index+direction)):null;}
// IDs1–6 occupy the exposed right-hand ice ring; fixed nested IDs melt first.
const ice=Array.from({length:12},(_,i)=>{const a=(i%6)*Math.PI/3;return [(i<6?164:78)+32*Math.cos(a),144+32*Math.sin(a)];});
const liquid=[[243,182],[273,182],[305,182],[258,155],[289,156],[320,156],[243,128],[273,129],[305,130],[258,102],[289,104],[319,104]];
export function phaseDots(index){const s=phaseStage(index);return s?ice.map((p,i)=>({id:i+1,x:i<s.liquid?liquid[i][0]:p[0],y:i<s.liquid?liquid[i][1]:p[1],radius:phaseRadius,phase:i<s.liquid?'liquid':'ice'})):null;}
export const phaseTemperature=t=>t===-5?'minus five degrees Celsius':t===0?'zero degrees Celsius':'plus five degrees Celsius';
let visit=null;
export function resetWaterPhase(){visit=null;}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,index:0,selected:1,status:'',details:{}};return visit;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(id,text,disabled=false)=>`<button type="button" data-phase-action="${id}"${disabled?' disabled':''}>${text}</button>`;
function picture(v){const s=phaseStage(v.index),dots=phaseDots(v.index);return `<figure class="phase-jar"><svg viewBox="0 0 370 245" role="img" aria-labelledby="phase-picture-title phase-picture-desc"><title id="phase-picture-title">${s.solid} symbols in ice and ${s.liquid} in liquid</title><desc id="phase-picture-desc">Same twelve water molecule symbols in a closed-water model. Open six-dot ice patterns on the left, a closer irregular liquid group on the right. The amber ring follows particle ${v.selected}, which is in ${dots[v.selected-1].phase}. Arrows are explanatory, not measured motion.</desc><defs><marker id="phase-arrow" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L6 3 0 6" fill="#397958"/></marker></defs><path class="phase-glass" d="M27 41H343V211Q343 227 327 227H43Q27 227 27 211Z"/><path class="phase-lid" d="M20 27H350V42H20Z"/><text x="185" y="69" text-anchor="middle">Water stays inside · energy can cross</text>${dots.map(d=>`<g data-phase-dot="${d.id}" data-phase="${d.phase}">${d.phase==='ice'?`<path d="M${d.x-7} ${d.y-15}h14" marker-start="url(#phase-arrow)" marker-end="url(#phase-arrow)"/>`:`<path d="M${d.x-8} ${d.y-15}l13 -5" marker-end="url(#phase-arrow)"/>`}<circle data-phase-symbol cx="${d.x}" cy="${d.y}" r="7"/>${d.id===v.selected?`<circle class="phase-ring" cx="${d.x}" cy="${d.y}" r="12"/>`:''}</g>`).join('')}</svg><figcaption><span>Ice: open pattern ↔ vibration</span><span>Liquid: changing neighbors ↗</span></figcaption></figure>`;}
function trace(v){return `<figure class="phase-trace"><svg viewBox="0 0 370 105" role="img" aria-labelledby="phase-trace-title"><title id="phase-trace-title">Temperature by model stage: minus five, zero, zero, zero, zero, plus five degrees Celsius. Current stage ${v.index+1}. Stages are not equal energy or time.</title><path d="M48 10V74H351" class="phase-axis"/><text x="38" y="23" text-anchor="end">+5</text><text x="38" y="46" text-anchor="end">0</text><text x="38" y="69" text-anchor="end">−5</text><text x="5" y="10">°C</text><path class="phase-line" d="M64 64L118 41H280L334 18"/>${phaseStages.map((s,i)=>`<circle data-phase-trace="${i}" cx="${64+54*i}" cy="${41-s.temperature*4.6}" r="${i===v.index?6:3}" class="${i===v.index?'selected':''}"/><text x="${64+54*i}" y="91" text-anchor="middle">${i+1}</text>`).join('')}</svg><figcaption>Model stage · not equal energy or time</figcaption></figure>`;}
export function waterPhasePage(book,owner){const v=current(book,owner),s=phaseStage(v.index),d=phaseDots(v.index)[v.selected-1];return `<link rel="stylesheet" href="./water-phase.css"><section class="phase-room" data-water-phase-root><header><a href="#science/play">← Back to the Water Lab</a><p class="eyebrow">Water Lab · tiny-view investigation</p><h1 id="phase-title" tabindex="-1">Ice and warmth</h1><p>Willowbank’s friends have a winter question: what changes when ice melts? Try a model of pure water.</p></header><div class="phase-workbench"><div class="phase-pictures">${picture(v)}${trace(v)}</div><section class="phase-controls" aria-label="Change the model"><p class="phase-stage">Stage ${v.index+1} of 6</p><h2>${s.title}</h2><p class="phase-temperature"><span aria-hidden="true">${s.temperature<0?'−5':s.temperature>0?'+5':'0'} °C</span><span class="sr-only">${phaseTemperature(s.temperature)}</span></p><p class="phase-count">${s.solid} in ice · ${s.liquid} in liquid</p><div class="phase-energy">${button('out','← Energy out',v.index===0)}${button('in','Energy in →',v.index===5)}</div><p class="phase-explanation">${s.body}</p><p class="phase-follow">Following particle ${v.selected}: in ${d.phase}.</p><div class="phase-tools">${button('follow','Follow another particle')}${button('reset','Start again')}</div><p class="phase-status" role="status">${esc(v.status)}</p></section></div><p class="phase-boundary"><strong>Same water; same mass.</strong> This model is closed to water entering or leaving. Energy can cross its boundary.</p><details data-phase-details="try" ${v.details.try?'open':''}><summary>Try a different direction</summary><p>Remove energy. Can you find two stages with the same temperature but different amounts of ice? Tell someone what changed and what stayed the same. This conversation isn’t recorded or scored.</p></details><details data-phase-details="model" ${v.details.model?'open':''}><summary>About the tiny-view model</summary><p>Each particle symbol stands for one water molecule. Ice still vibrates; liquid molecules move past their neighbors. Melting changes the arrangement between molecules; the bonds within each water molecule stay intact. No new substance is made.</p><p>This is pure water at ordinary air pressure, heated and cooled slowly so the ice and water share one temperature. Each button moves one model stage, not an equal amount of energy or time. Melting all the ice takes much more energy than warming the ice or water by five degrees.</p><p>A real storm puddle may contain other substances. These stages don’t predict its temperature. A dripping icicle loses water as drops leave it; our closed model keeps its water. The model leaves out the small amount of water vapor above the sample.</p><p>The open ice patterns have holes; the liquid group has fewer big gaps. Symbols, sizes, arrows and spacing aren’t to scale or measured speeds or density. This is an explanatory drawing, not a view through a real magnifier. The model stops at minus five and plus five degrees Celsius; real water can be colder or hotter. No real ice or equipment is needed.</p></details><details data-phase-details="table" ${v.details.table?'open':''}><summary>Read all six stages</summary><table><caption>Pure-water model · stages are not equal energy or time</caption><thead><tr><th>Stage</th><th>Temperature</th><th>Ice symbols</th><th>Liquid symbols</th></tr></thead><tbody>${phaseStages.map((x,i)=>`<tr><th>${i+1}</th><td>${phaseTemperature(x.temperature)}</td><td>${x.solid}</td><td>${x.liquid}</td></tr>`).join('')}</tbody></table></details><details data-phase-details="sources" ${v.details.sources?'open':''}><summary>Grown-ups: sources and limits</summary><p>Supplied teaching, not an assessment, physical experiment or measured mass. No model steps or discussion are added to the notebook. This picture doesn’t model supercooling, saltwater, precise energy amounts or real floodwater.</p><ul><li><a href="https://highschoolenergy.acs.org/what-is-energy/thermometers.html" target="_blank" rel="noopener noreferrer">ACS: energy and thermometers</a></li><li><a href="https://www.acs.org/middleschoolchemistry/lessonplans/chapter2/lesson5.html" target="_blank" rel="noopener noreferrer">ACS: melting</a></li><li><a href="https://www.usgs.gov/water-science-school/science/water-density" target="_blank" rel="noopener noreferrer">USGS: water density</a></li></ul></details></section>`;}
export function bindWaterPhase(book,{explorerId,notebook,isActive,render,stopSpeech,stopSound}){const root=document.querySelector('[data-water-phase-root]');if(!root)return;const v=current(book,explorerId()),live=()=>visit===v&&root.isConnected&&notebook()===book&&explorerId()===v.owner&&isActive();root.querySelectorAll('[data-phase-details]').forEach(e=>e.addEventListener('toggle',()=>{if(live())v.details[e.dataset.phaseDetails]=e.open;}));root.querySelectorAll('[data-phase-action]').forEach(b=>b.addEventListener('click',()=>{if(!live()||b.disabled)return;stopSpeech();stopSound();for(const d of root.querySelectorAll('[data-phase-details]'))v.details[d.dataset.phaseDetails]=d.open;const a=b.dataset.phaseAction;if(a==='in'||a==='out'){v.index=phaseStep(v.index,a==='in'?1:-1);v.status=a==='in'?'Energy entered the model.':'Energy left the model.';}else if(a==='follow'){v.selected=v.selected%12+1;v.status='Following another particle.';}else if(a==='reset'){v.index=0;v.selected=1;v.status='Back to cold ice, following particle 1.';}else return;render();let target=document.querySelector(`[data-phase-action="${a}"]`);if(target?.disabled)target=document.querySelector(`[data-phase-action="${a==='in'?'out':'in'}"]`);target?.focus({preventScroll:true});}));}
